 const scenario=refinanceScenario(name),ids=new Map<string,string>();
 for(const ref of scenario.body.expenses??[]){const row=body.expenses?.find(row=>row.id===ref.id&&Boolean(row.excluded)===Boolean(ref.excluded))||body.expenses?.find(row=>row.label===ref.label&&row.category===ref.category&&row.source_group_key===ref.source_group_key&&Boolean(row.excluded)===Boolean(ref.excluded));if(row)ids.set(ref.id,row.id);}
