 let json=JSON.stringify({goal:scenario.goal,evaluation:scenario.evaluation,guidance:scenario.guidance,evidence:scenario.evidence});for(const[oldId,newId]of ids)json=json.replaceAll(oldId,newId);return JSON.parse(json) as {goal:OperatingGoalRead;evaluation:OperatingEvaluation;guidance:OperatingGuidance;evidence:OperatingEvidence};
